<?php require_once __DIR__.'/include/config.php';require_once __DIR__.'/../include/billing.php';hms_start_session();hms_require_role('admin');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;if(!hms_billing_ready($con))exit(hms_billing_notice());$p=hms_db_query($con,'SELECT p.*,i.invoice_number,u.fullName patient FROM billing_payments p JOIN billing_invoices i ON i.id=p.invoice_id JOIN users u ON u.id=i.patient_user_id WHERE p.id=?',[$id])->fetch_assoc();if(!$p){http_response_code(404);exit('Receipt not found.');?><?php } ?><!doctype html><html><head><meta charset="utf-8"><title>Receipt</title><link rel="stylesheet" href="vendor/bootstrap/css/bootstrap.min.css"><style>@media print{button,a{display:none}}main{max-width:700px;margin:30px auto}</style></head><body><main><a href="invoice.php?id=<?=hms_h($p['invoice_id'])?>">Back</a><button onclick="print()" class="btn btn-primary pull-right">Print receipt</button><h1>MedTech Hospital</h1><h2>Receipt <?=hms_h($p['receipt_number'])?></h2><p>Received from <?=hms_h($p['patient'])?> for invoice <?=hms_h($p['invoice_number'])?>.</p><h3>₹<?=number_format((float)$p['amount'],2)?></h3><p><?=hms_h($p['received_at'])?> · <?=hms_h($p['payment_method'])?><br>Reference: <?=hms_h($p['transaction_reference'])?></p></main></body></html>
